  margin: 6px 0 5px 0;
  text-transform: uppercase;
  letter-spacing: 1px;
  background: linear-gradient(to right, #f900ff, #00d9ff);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  position: relative;
  display: inline-block;
}

#settingsPopup h3::after {
  content: '';
  position: absolute;
  width: 60%;
  height: 2px;
  bottom: -5px;
  left: 20%;
  background: linear-gradient(to right, #f900ff, #00d9ff);
