}

#settingsPopup h2 {
  color: white;
  font-size: 12px;
  font-weight: 600;
  margin: 0 0 8px 0;
  padding: 8px;
  background: linear-gradient(90deg, rgba(0,0,0,0.8) 0%, rgba(0,0,0,0.9) 100%);
