  color: #ff3366;
  font-weight: 700;
  display: block;
  margin-top: 3px;
  animation: warningPulse 2s infinite alternate;
}

@keyframes warningPulse {
  from { text-shadow: 0 0 5px rgba(255, 51, 102, 0.5); }
  to { text-shadow: 0 0 15px rgba(255, 51, 102, 0.9), 0 0 20px rgba(255, 51, 102, 0.7); }
}

#settingsPopup h3 {
  color: white;
  font-size: 12px;
