  transform: translate(-50%, -50%) scale(0.8);
}

#settingsPopup h2 {
  color: white;
  font-size: 12px;
  font-weight: 600;
  margin: 0 0 8px 0;
  padding: 8px;
  background: linear-gradient(90deg, rgba(0,0,0,0.8) 0%, rgba(0,0,0,0.9) 100%);
  border-radius: 6px;
  text-shadow: 0 0 5px rgba(255, 255, 255, 0.5);
  border: 1px solid rgba(248, 0, 255, 0.3);
  line-height: 1.4;
}

#settingsPopup h2 .warning-text {
  color: #ff3366;
  font-weight: 700;
  display: block;
  margin-top: 3px;
  animation: warningPulse 2s infinite alternate;
}

@keyframes warningPulse {
  from { text-shadow: 0 0 5px rgba(255, 51, 102, 0.5); }
  to { text-shadow: 0 0 15px rgba(255, 51, 102, 0.9), 0 0 20px rgba(255, 51, 102, 0.7); }
}

#settingsPopup h3 {
  color: white;
  font-size: 12px;
  font-weight: 700;
  margin: 6px 0 5px 0;
  text-transform: uppercase;
  letter-spacing: 1px;
  background: linear-gradient(to right, #f900ff, #00d9ff);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  position: relative;
  display: inline-block;
}

#settingsPopup h3::after {
  content: '';
  position: absolute;
  width: 60%;
  height: 2px;
  bottom: -5px;
  left: 20%;
  background: linear-gradient(to right, #f900ff, #00d9ff);
  border-radius: 10px;
}

.telegram-link {
  display: inline-block;
  margin-bottom: 6px;
}

.telegram-link img {
  width: 32px;
  height: 32px;
  cursor: pointer;
  border-radius: 50%;
  border: 2px solid rgba(255, 255, 255, 0.2);
  box-shadow: 0 0 15px rgba(248, 0, 255, 0.5);
  transition: all 0.3s ease;
}

.telegram-link img:hover {
  transform: scale(1.1) rotate(5deg);
  box-shadow: 0 0 20px rgba(248, 0, 255, 0.7);
  border-color: rgba(255, 255, 255, 0.4);
}

#settingsPopup label {
  display: block; 
  margin-bottom: 6px; 
  color: rgba(255, 255, 255, 0.9);
  font-size: 11px;
  font-weight: 500;
  text-align: left;
}

#settingsPopup input, #settingsPopup select {
  width: 100%; 
  padding: 7px; 
  margin-top: 2px; 
  border: 2px solid rgba(255, 255, 255, 0.2); 
  border-radius: 8px; 
  background: rgba(255, 255, 255, 0.1);
  color: white;
  font-size: 13px;
  box-sizing: border-box;
  font-family: 'Roboto', sans-serif;
  transition: all 0.3s ease;
}

#settingsPopup input::placeholder {
  color: rgba(255, 255, 255, 0.5);
}

#settingsPopup input:focus, #settingsPopup select:focus {
  outline: none;
  border-color: #f900ff;
  box-shadow: 0 0 0 3px rgba(248, 0, 255, 0.3);
  background: rgba(255, 255, 255, 0.15);
}

/* Country Flag Select Dropdown Styling */
#countryFlagSelect {
  background: rgba(30, 11, 54, 0.9);
  color: white;
  cursor: pointer;
}

#countryFlagSelect option {
  background: #1e0b36;
  color: white;
  padding: 10px;
  font-size: 14px;
}

#countryFlagSelect option:hover {
  background: rgba(248, 0, 255, 0.2);
}

#countryFlagSelect option:checked {
  background: linear-gradient(135deg, #8333ff, #f900ff);
  color: white;
  font-weight: 600;
}

#settingsPopup small {
  display: block;
  margin-top: -4px;
  margin-bottom: 6px;
  color: rgba(255, 255, 255, 0.6);
  font-size: 8px;
  font-style: italic;
  text-align: left;
}

#settingsPopup button {
  width: 100%;
  padding: 7px;
  margin-top: 5px;
  border: none;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.3s ease;
  text-transform: uppercase;
  letter-spacing: 1px;
  position: relative;
  overflow: hidden;
  font-family: 'Roboto', sans-serif;
}

#settingsPopup button::before {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.3), transparent);
  transition: all 0.5s ease;
}

#settingsPopup button:hover::before {
  left: 100%;
}

#settingsPopup button:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.3);
}

#settingsPopup button:active {
  transform: translateY(0);
}

#saveButton, #verifyBtn, #setDemoBtn {
  background: linear-gradient(135deg, #8333ff, #f900ff);
  color: white;
  box-shadow: 0 5px 15px rgba(0, 0, 0, 0.2);
}

#onlinePaymentActiveBtn {
  background: linear-gradient(135deg, #10b981, #059669) !important;
  color: white !important;
  box-shadow: 0 5px 15px rgba(16, 185, 129, 0.35) !important;
  margin-top: 8px !important;
  width: 100%;
  font-weight: 700 !important;
}

#onlinePaymentActiveBtn:hover {
  box-shadow: 0 8px 20px rgba(16, 185, 129, 0.45) !important;
}

#settingsPopup button.close-btn {
  background: linear-gradient(135deg, #ff3366, #ff5757);
  color: white;
  box-shadow: 0 5px 15px rgba(0, 0, 0, 0.2);
}

#settingsPopup button:disabled {
  background: #6c757d;
  cursor: not-allowed;
  opacity: 0.6;
}

#settingsPopup button:disabled:hover {
  transform: none;
  box-shadow: none;
}

#licenseSection, #demoBalanceSection {
  margin-top: 8px;
  padding: 10px;
  background: rgba(255, 255, 255, 0.05);
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  transition: all 0.3s ease;
}

#licenseSection.hide {
  opacity: 0;
  max-height: 0;
  padding: 0;
  margin: 0;
  overflow: hidden;
  border: none;
}

#demoBalanceSection {
  opacity: 0;
  max-height: 0;
  overflow: hidden;
  padding: 0;
  margin: 0;
  border: none;
}

#demoBalanceSection.show {
  opacity: 1;
  max-height: 500px;
  padding: 12px;
  margin-top: 10px;
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.message-popup {
  position: fixed;
  top: 80px;
  right: 20px;
  padding: 15px 20px;
  color: white;
  border-radius: 12px;
  font-size: 14px;
  font-weight: 600;
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.3);
  opacity: 0;
  transform: translateY(-20px);
  transition: opacity 0.5s ease, transform 0.5s ease;
  z-index: 10001;
  max-width: 300px;
  text-align: center;
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  font-family: 'Roboto', sans-serif;
}

.message-popup.show {
  opacity: 1;
  transform: translateY(0);
}

.message-popup.success {
  background: rgba(0, 255, 163, 0.15);
  color: #00ffa3;
  box-shadow: 0 0 15px rgba(0, 255, 163, 0.3);
  border: 1px solid rgba(0, 255, 163, 0.2);
}

.message-popup.error {
  background: rgba(255, 51, 102, 0.15);
  color: #ff3366;
  box-shadow: 0 0 15px rgba(255, 51, 102, 0.3);
  border: 1px solid rgba(255, 51, 102, 0.2);
}

#centeredDeveloperMessage {
  position: fixed; 
  top: 50%; 
  left: 50%;
  transform: translate(-50%, -50%);
  background: rgba(0, 0, 0, 0.9);
  color: white; 
  padding: 30px 50px; 
  border-radius: 15px;
  font-size: 20px; 
  font-weight: bold;
  z-index: 10004; 
  opacity: 0;
  transition: opacity 0.5s ease;
  box-shadow: 0 10px 30px rgba(0,0,0,0.5);
  border: 2px solid rgba(248, 0, 255, 0.5);
  font-family: 'Roboto', sans-serif;
  text-align: center;
}

/* Hide original flag/name while loading and prepare for instant replacement */
.jisanx-leaderboard-loading .position__header-name {
    opacity: 0 !important;
}

#licenseInput, #demoBalanceInput {
  width: 100%;
  padding: 8px;
  font-size: 12px;
  border: 2px solid rgba(255, 255, 255, 0.2);
  border-radius: 10px;
  margin-bottom: 8px;
  background: rgba(255, 255, 255, 0.1);
  color: white;
  font-family: 'Roboto', sans-serif;
  box-sizing: border-box;
}

#cheatCodeDisplay {
  font-size: 8px;
  padding: 6px;
  margin-top: 6px;
  line-height: 1.4;
  background: rgba(0, 0, 0, 0.3);
  border-radius: 6px;
  color: rgba(255, 255, 255, 0.7);
  border: 1px solid rgba(255, 255, 255, 0.1);
  word-wrap: break-word;
}

.verified-badge {
  background: rgba(0, 255, 163, 0.2);
  color: #00ffa3;
  padding: 4px 10px;
  border-radius: 6px;
  font-size: 10px;
  font-weight: 600;
  margin-top: 6px;
  display: inline-block;
  border: 1px solid rgba(0, 255, 163, 0.3);
}

.unverified-badge {
  background: rgba(255, 51, 102, 0.2);
  color: #ff3366;
  padding: 4px 10px;
  border-radius: 6px;
  font-size: 10px;
  font-weight: 600;
  margin-top: 10px;
  display: inline-block;
  border: 1px solid rgba(255, 51, 102, 0.3);
}

#demoBalanceStatus, #verificationStatus {
  margin-top: 10px;
  font-size: 12px;
  font-weight: 500;
}

/* To reduce unnecessary space */
#settingsPopup br {
  display: none;
}

/* CSS for refresh button */
#refreshBalanceBtn {
  position: absolute; 
  top: 26px; 
  right: 8px;
  cursor: pointer;
  width: 22px; 
  height: 22px;
  display: flex; 
  align-items: center; 
  justify-content: center;
  border-radius: 50%; 
  background: rgba(248, 0, 255, 0.2);
  border: 2px solid rgba(248, 0, 255, 0.4);
  transition: all 0.3s ease;
}

#refreshBalanceBtn:hover { 
  background: rgba(248, 0, 255, 0.3);
  transform: scale(1.1);
  box-shadow: 0 0 15px rgba(248, 0, 255, 0.5);
}

#refreshBalanceBtn svg { 
  width: 12px; 
  height: 12px; 
  fill: #f900ff; 
}

@keyframes spin { 
  from { transform: rotate(0deg); } 
  to { transform: rotate(360deg); } 
}

.spinning { 
  animation: spin 0.6s linear; 
}

/* Mobile Responsive */
@media screen and (max-width: 480px) {
  #settingsPopup {
    padding: 8px 10px;
    max-width: 95%;
    max-height: calc(100vh - 10px);
  }

  #settingsPopup h2 {
    font-size: 10px;
    padding: 6px;
    margin-bottom: 5px;
    line-height: 1.3;
  }

  #settingsPopup h3 {
    font-size: 10px;
    margin: 5px 0 4px 0;
  }

  #settingsPopup h3::after {
    bottom: -3px;
  }

  .telegram-link {
    margin-bottom: 4px;
  }

  .telegram-link img {
    width: 26px;
    height: 26px;
  }

  #settingsPopup input, #settingsPopup select {
    padding: 5px;
    font-size: 11px;
  }

  #settingsPopup button {
    padding: 5px;
    font-size: 11px;
  }

  #settingsPopup label {
    font-size: 9px;
    margin-bottom: 4px;
  }

  #settingsPopup small {
    font-size: 7px;
    margin-top: -3px;
    margin-bottom: 4px;
  }

  #refreshBalanceBtn {
    top: 24px;
    width: 22px;
    height: 22px;
  }

  #refreshBalanceBtn svg {
    width: 11px;
    height: 11px;
  }

  #licenseSection, #demoBalanceSection {
    padding: 6px;
    margin-top: 5px;
  }

  #demoBalanceSection.show {
    padding: 6px;
    margin-top: 5px;
  }

  #licenseInput, #demoBalanceInput {
    padding: 5px;
    font-size: 10px;
    margin-bottom: 4px;
  }

  #cheatCodeDisplay {
    font-size: 7px;
    padding: 4px;
    margin-top: 5px;
  }

  .verified-badge, .unverified-badge {
    padding: 3px 8px;
    font-size: 9px;
  }
}

/* Custom overlay panel for leaderboard information */
.custom-overlay-panel {
  z-index: 10000 !important;
  pointer-events: auto !important;
  position: fixed !important;
}

/* Hide only the specific original panel that has custom overlay */
.panel-leader-board__information.hide-original {
  opacity: 0 !important;
  pointer-events: none !important;
  visibility: hidden !important;
}

/* Pre-hide any panel that might be for user's position - will be shown if not user's */
.panel-leader-board__information:not(.custom-overlay-panel) {
  opacity: 0 !important;
  visibility: hidden !important;
  transition: none !important;
}

/* Show original panel only for other users (will be set by JS) */
.panel-leader-board__information.show-original {
  opacity: 1 !important;
  visibility: visible !important;
}

